// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for config load and checks
// Flo: defaults > override keys > reject bad values > expand ~
// I/O: JSON text > Conf or BadConfig (no leaks)
// Run: zig build test -Dfile=cf-conf-load-test.zig
// ===================================================================
const std = @import("std"); const cfgz = @import("cf-conf-load.zig");
fn arenNew() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
test "empty object gives safe defaults" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confParse(aren.allocator(), "{}"); try std.testing.expectEqual(@as(u32, 3), conf.capz_post_dayz); try std.testing.expect(!conf.smar_mode_enab); try std.testing.expectEqual(@as(u32, 14), conf.warm_dayz_coun); }
test "keys override" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confParse(aren.allocator(), "{\"capz_post_dayz\":1,\"type_dely_msec\":[40,80]}"); try std.testing.expectEqual(@as(u32, 1), conf.capz_post_dayz); try std.testing.expectEqual(@as(u32, 80), conf.type_dely_msec[1]); }
test "bad values are rejected" { var aren = arenNew(); defer aren.deinit(); const bads = [_][]const u8{ "{\"type_dely_msec\":[300,100]}", "{\"quie_hour_rang\":[25,1]}", "{\"retr_coun_maxz\":0}", "{\"base_urlz_main\":\"ftp://x\"}", "{\"smar_chai_orde\":[\"gpt\"]}", "not json" }; for (bads) |txt| try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), txt)); }
test "tilde expands with home, empty home refused" { const allo = std.testing.allocator; const out = try cfgz.pathExpa(allo, "/home/u", "~/.fb-prof"); defer allo.free(out); try std.testing.expectEqualStrings("/home/u/.fb-prof", out); try std.testing.expectError(error.BadConfig, cfgz.pathExpa(allo, "", "~/x")); const abs = try cfgz.pathExpa(allo, "", "/abs/p"); defer allo.free(abs); try std.testing.expectEqualStrings("/abs/p", abs); }
test "data folder mirrors the app path under the tena root, per OS" { const allo = std.testing.allocator; const conf: cfgz.Conf = .{}; try std.testing.expectEqualStrings("E:\\.zz-base-home-tena\\as-apps\\ch-chat\\fb-face-webs", conf.data_loca_wind); try std.testing.expectEqualStrings("~/.zz-base-home-tena/as-apps/ch-chat/fb-face-webs", conf.data_loca_unix); const dir = try cfgz.dataDir(allo, "/home/u", conf); defer allo.free(dir); try std.testing.expect(std.mem.find(u8, dir, "as-apps") != null); const sub = try cfgz.subDir(allo, "/home/u", conf, "stat"); defer allo.free(sub); try std.testing.expect(std.mem.endsWith(u8, sub, "stat")); try std.testing.expect(std.mem.find(u8, sub, ".fb-") == null); }
test "missing config file returns defaults" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confLoad(aren.allocator(), std.testing.io, "no-such-file-zz.json"); try std.testing.expectEqual(@as(u32, 30), conf.capz_comm_dayz); }
test "the shipped aa-conf-main.json parses and agrees with the code defaults" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const conf = try cfgz.confLoad(aren.allocator(), std.testing.io, "aa-conf-main.json"); const dflt: cfgz.Conf = .{}; try std.testing.expectEqual(dflt.capz_post_dayz, conf.capz_post_dayz); try std.testing.expectEqual(dflt.capz_stor_dayz, conf.capz_stor_dayz); try std.testing.expectEqual(dflt.wait_maxx_minu, conf.wait_maxx_minu); try std.testing.expectEqual(dflt.cool_perc_caps, conf.cool_perc_caps); try std.testing.expectEqualStrings(dflt.lang_main_code, conf.lang_main_code); try std.testing.expectEqualStrings(dflt.data_loca_wind, conf.data_loca_wind); try std.testing.expectEqualStrings(dflt.data_loca_unix, conf.data_loca_unix); try std.testing.expectEqual(@as(usize, 1), conf.flow_list.len); try std.testing.expectEqualStrings("morning", conf.flow_list[0].name); }
test "Phase 3 defaults: money cap and spend cap are 0, secrets folder mirrors the app path, map caps are low" { const dflt: cfgz.Conf = .{}; try std.testing.expectEqual(@as(u32, 0), dflt.capz_mone_dayz); try std.testing.expectEqual(@as(u32, 0), dflt.mone_spen_capz); try std.testing.expectEqual(@as(u32, 12), dflt.capz_acct_dayz); try std.testing.expectEqual(@as(u32, 40), dflt.capz_help_dayz); try std.testing.expectEqualStrings("~/.zz-base-home-secr/as-apps/ch-chat/fb-face-webs", dflt.secr_loca_main); try std.testing.expectEqual(@as(u32, 25), dflt.map_page_maxx); try std.testing.expect(dflt.map_seed_list.len > 10); for (dflt.map_seed_list) |sd| try std.testing.expect(sd[0] == '/'); }
test "confPath finds any path key by name and returns empty for unknown or non-path keys" { const dflt: cfgz.Conf = .{}; try std.testing.expectEqualStrings("/accountscenter", cfgz.confPath(dflt, "path_acct_cent")); try std.testing.expectEqualStrings("/billing_hub/payment_methods", cfgz.confPath(dflt, "pbiz_paym_main")); try std.testing.expectEqualStrings("", cfgz.confPath(dflt, "path_nope_nope")); try std.testing.expectEqualStrings("", cfgz.confPath(dflt, "capz_post_dayz")); }
test "bad map settings are rejected" { var aren = arenNew(); defer aren.deinit(); const bads = [_][]const u8{ "{\"map_page_maxx\":0}", "{\"map_page_maxx\":500}", "{\"map_deep_maxx\":9}", "{\"map_seed_list\":[\"nope\"]}", "{\"map_allo_list\":[\"\"]}", "{\"secr_loca_main\":\"\"}" }; for (bads) |txt| try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), txt)); const okay = try cfgz.confParse(aren.allocator(), "{\"map_seed_list\":[\"/settings\"],\"capz_mone_dayz\":2,\"mone_spen_capz\":30}"); try std.testing.expectEqual(@as(usize, 1), okay.map_seed_list.len); try std.testing.expectEqual(@as(u32, 30), okay.mone_spen_capz); }
test "the shipped file carries the Phase 3 keys with safe values" { var aren = arenNew(); defer aren.deinit(); const conf = try cfgz.confLoad(aren.allocator(), std.testing.io, "aa-conf-main.json"); try std.testing.expectEqual(@as(u32, 0), conf.capz_mone_dayz); try std.testing.expectEqual(@as(u32, 0), conf.mone_spen_capz); try std.testing.expectEqual(@as(u32, 12), conf.capz_acct_dayz); try std.testing.expectEqual(@as(u32, 40), conf.capz_help_dayz); try std.testing.expectEqualStrings("~/.zz-base-home-secr/as-apps/ch-chat/fb-face-webs", conf.secr_loca_main); }
test "account limits: defaults, bounds and the per-account data folder" { const dflt: cfgz.Conf = .{}; try std.testing.expectEqual(@as(u32, 5), dflt.acct_maxx_coun); try std.testing.expectEqual(@as(u32, 300), dflt.acct_gap_secs[0]); try std.testing.expectEqual(@as(u32, 1200), dflt.acct_gap_secs[1]); var aren = arenNew(); defer aren.deinit(); const bads = [_][]const u8{ "{\"acct_maxx_coun\":0}", "{\"acct_maxx_coun\":21}", "{\"acct_gap_secs\":[900,100]}" }; for (bads) |txt| try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), txt)); const okay = try cfgz.confParse(aren.allocator(), "{\"acct_maxx_coun\":20,\"acct_gap_secs\":[60,120]}"); try std.testing.expectEqual(@as(u32, 20), okay.acct_maxx_coun); const dir = try cfgz.acctDir(std.testing.allocator, "/home/u", dflt, "shop1", "stat"); defer std.testing.allocator.free(dir); try std.testing.expect(std.mem.endsWith(u8, dir, "stat")); try std.testing.expect(std.mem.find(u8, dir, "shop1") != null); try std.testing.expect(std.mem.find(u8, dir, "acct") != null); }
test "an unknown key is refused: top level, nested, and a typo of a real key" { var aren = arenNew(); defer aren.deinit(); const allo = aren.allocator(); const bads = [_][]const u8{ "{\"zzzz\":5}", "{\"capz_post_day\":1}", "{\"flow_list\":[{\"name\":\"a\",\"jobz\":[]}]}" }; for (bads) |txt| try std.testing.expectError(error.BadConfig, cfgz.confParse(allo, txt)); try std.testing.expectEqualStrings("zzzz", cfgz.confKeyz(allo, "{\"capz_post_dayz\":1,\"zzzz\":5}").?); try std.testing.expect(cfgz.confKeyz(allo, "{\"capz_post_dayz\":1}") == null); }
test "the shipped aa-conf-main.json passes the strict loader" { var aren = arenNew(); defer aren.deinit(); _ = try std.Io.Dir.cwd().statFile(std.testing.io, "aa-conf-main.json", .{}); _ = try cfgz.confLoad(aren.allocator(), std.testing.io, "aa-conf-main.json"); }
test "human-pace floors: no setting can make typing, actions, scale or the mouse fixed or instant" { var aren = arenNew(); defer aren.deinit(); const allo = aren.allocator(); const bads = [_][]const u8{ "{\"type_dely_msec\":[10,200]}", "{\"type_dely_msec\":[100,100]}", "{\"type_dely_msec\":[100,120]}", "{\"acti_dely_secs\":[1,9]}", "{\"acti_dely_secs\":[5,5]}", "{\"time_scal_perc\":0}", "{\"time_scal_perc\":10}", "{\"mous_step_coun\":3}" }; for (bads) |txt| try std.testing.expectError(error.BadConfig, cfgz.confParse(allo, txt)); _ = try cfgz.confParse(allo, "{\"type_dely_msec\":[30,45],\"acti_dely_secs\":[2,3],\"time_scal_perc\":50,\"mous_step_coun\":8}"); }
test "a fixed random seed is refused (human pace needs real entropy)" { var aren = arenNew(); defer aren.deinit(); try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), "{\"rand_seed_numb\":5}")); _ = try cfgz.confParse(aren.allocator(), "{\"rand_seed_numb\":0}"); }
